L46_1 = "SAYO_NPC_NANAHARA_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "C"
L46_1 = "찾고 있었습니다."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "探しましたよ。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "We’ve been looking for you."
L45_1.m_Talk_ENG = L46_1
L46_1 = "我們一直在找您呢。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ฉันกำลังตามหาอยู่เลยค่ะ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Chúng tôi đã tìm kiếm cô suốt đấy."
L45_1.m_Talk_VTN = L46_1
L46_1 = "我们可是一直在找你呢。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Wir haben nach Ihnen gesucht."
L45_1.m_Talk_DEU = L46_1
L46_1 = "La partie de cache-cache est terminée."
L45_1.m_Talk_FRA = L46_1
