L47_1 = "NANAHARA_ACT4_STAGE3_END@46#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 46
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3600406
L46_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_Face = "UNIT_HATE"
L47_1 = "KANADE_JAPAN_NULL_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "C"
L47_1 = "사요! 네가 감히, 당주님을 배반하다니!"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "小夜！　貴様がご当主様を裏切るとは！"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Sayo! You dare betray Lady Nanahara!"
L46_1.m_Talk_ENG = L47_1
L47_1 = "小夜！你敢背叛堂主！"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ซาโยะ! เธอกล้าดีนักนะที่ทรยศผู้นำตระกูลน่ะ!"
L46_1.m_Talk_THA = L47_1
L47_1 = "Sayo! Cô dám phản bội tộc trưởng!"
L46_1.m_Talk_VTN = L47_1
L47_1 = "小夜！你竟敢背叛家主！"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Sayo! Wie kannst du es wagen, Frau Nanahara zu hintergehen?!"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Sayo ! Comment oses-tu trahir Dame Nanahara !"
L46_1.m_Talk_FRA = L47_1
