L50_1 = "NANAHARA_ACT4_STAGE3_END@49#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 49
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3600406
L49_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_Face = "UNIT_SURPRISE"
L50_1 = "SAYO_NPC_NANAHARA_NULL"
L49_1.m_CharStrID = L50_1
L50_1 = "R"
L49_1.m_Pos = L50_1
L50_1 = "뭔가 사소한 오해가 있는 것 같군요."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "どうやら少し誤解があるようですね。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "There must be a misunderstanding."
L49_1.m_Talk_ENG = L50_1
L50_1 = "好像有什麼誤會。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "น่าจะมีอะไรเข้าใจผิดกันนะคะ"
L49_1.m_Talk_THA = L50_1
L50_1 = "Chắc hẳn đã có một sự hiểu lầm."
L49_1.m_Talk_VTN = L50_1
L50_1 = "不不不，是你误会了。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Da muss es wohl ein Missverständnis gegeben haben."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Oh, on dirait qu'il y a un malentendu."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "NANAHARA_ACT4_STAGE3_END@50#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 50
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3600406
L50_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "SAYO_NPC_NANAHARA_NULL"
L50_1.m_CharStrID = L51_1
L51_1 = "R"
L50_1.m_Pos = L51_1
L51_1 = "목장의 돼지는 원래 자신의 역할을 몰라도 된답니다."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "養豚場の豚は本来、自分の役割を知らなくてもいいものです。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "A pig in a farm doesn’t have to know the role it serves."
L50_1.m_Talk_ENG = L51_1
L51_1 = "豬圈裡的豬本來就不需要知道自己的作用。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "หมูในคอกจะไปรู้ได้ยังไงว่าตัวเองมีหน้าที่อะไร"
L50_1.m_Talk_THA = L51_1
L51_1 = "Một con lợn trong trang trại không nhất thiết phải biết vai trò của nó."
L50_1.m_Talk_VTN = L51_1
L51_1 = "农场里待宰的猪猡，不需要知道自己的归宿。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Ein Schwein auf einer Farm muss nicht wissen, welche Rolle es spielt."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Voyez-vous, un cochon de ferme n'a pas besoin de savoir ce qu'il va lui arriver."
L50_1.m_Talk_FRA = L51_1
