L2_1 = "NANAHARA_ACT4_STAGE3_END@51#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 51
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 3600406
L1_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "SAYO_NPC_NANAHARA_NULL"
L1_1.m_CharStrID = L2_1
L2_1 = "R"
L1_1.m_Pos = L2_1
L2_1 = "주인이 그 사실을 알려주지 않았다고 해서 배반이라 부르진 않지요."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "飼い主がその事実を教えてくれなかったからといって、\n裏切りとは呼ばないでしょう。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "And I wouldn't call the farmer a betrayer just because he didn’t tell the pig what will happen to it."
L1_1.m_Talk_ENG = L2_1
L2_1 = "主人沒公開這個事實，就不算是背叛。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "และฉันคงไม่ไปบอกว่าคนเลี้ยงหมูเป็นคนทรยศ\nแค่เพราะเขาไม่บอกหมูว่ามันต้องเจอกับอะไรหรอกนะคะ"
L1_1.m_Talk_THA = L2_1
L2_1 = "Và tôi sẽ không gọi người nông dân là kẻ phản bội chỉ vì anh ta không nói cho con lợn biết chuyện gì sẽ xảy ra."
L1_1.m_Talk_VTN = L2_1
L2_1 = "大人也没有告诉她实情的必要，所以不能称之为背叛。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Und ich würde den Bauern nicht als Verräter bezeichnen, nur weil er dem Schwein nicht gesagt hat, was mit ihm passiert."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Mais cela ne fait pas du fermier un traître pour autant, juste pour lui avoir caché la vérité, si ?"
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "NANAHARA_ACT4_STAGE3_END@52#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 52
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 3600406
L2_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Face = "UNIT_PRIDE"
L3_1 = "SAYO_NPC_NANAHARA_NULL"
L2_1.m_CharStrID = L3_1
L3_1 = "R"
L2_1.m_Pos = L3_1
L3_1 = "뭐, 돼지의 분함은 동정할 수는 있겠지만…… 이건 어디까지나 순리이니까요."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "まあ、豚の悔しさに同情することはできますが……\nこれはあくまでも道理ですからね。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "You may feel sorry for the pig... but this is the way of nature."
L2_1.m_Talk_ENG = L3_1
L3_1 = "雖然可以同情豬的憤怒… 也算是人之常情。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "คุณอาจรู้สึกเสียใจกับเจ้าหมู... แต่นี่มันวิถีธรรมชาติค่ะ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Cô có thể cảm thấy tiếc cho con lợn... nhưng đây là điều tự nhiên."
L2_1.m_Talk_VTN = L3_1
L3_1 = "当然，你可以同情它们的愤怒……但这毕竟是自然法则。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Das Schwein tut dir vielleicht leid ... aber das ist der Lauf der Natur."
L2_1.m_Talk_DEU = L3_1
L3_1 = "On peut se sentir désolé pour le cochon autant qu'on veut... le monde est ainsi fait."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "NANAHARA_ACT4_STAGE3_END@53#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 53
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 3600406
L3_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
