L4_1 = "UNIT_SERIOUS"
L3_1.m_Face = L4_1
L4_1 = "KANADE_JAPAN_NULL_NULL"
L3_1.m_CharStrID = L4_1
L4_1 = "L"
L3_1.m_Pos = L4_1
L4_1 = "뻔뻔하구나."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "図々しいやつめ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "You have no shame."
L3_1.m_Talk_ENG = L4_1
L4_1 = "你真是厚顏無恥！"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เธอนี่ไร้ยางอายจริงๆ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Đồ không biết xấu hổ."
L3_1.m_Talk_VTN = L4_1
L4_1 = "真无耻。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Schäm dich!"
L3_1.m_Talk_DEU = L4_1
L4_1 = "N'importe quoi..."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "NANAHARA_ACT4_STAGE3_END@54#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 54
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 3600406
L4_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L5_1 = "SAYO_NPC_NANAHARA_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "R"
L4_1.m_Pos = L5_1
L5_1 = "그만 비켜 주시겠습니까? 당주께서 많이 괴로워하시는 것 같은데, 저희가 모시지요."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "そろそろ退いていただけますか？　\nご当主がかなり苦しんでおられるようですので、私たちがお付き添いいたします。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Could you please stand back? Lady Nanahara is obviously in great pain. Let us take care of her."
L4_1.m_Talk_ENG = L5_1
L5_1 = "麻煩讓一讓好嗎？堂主似乎很痛苦，讓我們來侍候吧。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ช่วยถอยไปหน่อยได้มั้ยคะ เห็นชัดเลยนายท่านนานะฮาระเจ็บปวดสาหัส ให้เราดูแลเธอเถอะค่ะ"
L4_1.m_Talk_THA = L5_1
L5_1 = "Cô có thể vui lòng lùi lại được không? Chủ Nhân Nanahara rõ ràng đang rất đau đớn. Hãy để chúng tôi chăm sóc cô ấy."
L4_1.m_Talk_VTN = L5_1
L5_1 = "你还是快点让开吧？家主看起来很痛苦，让我们帮她解脱吧。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Könnten Sie bitte zurücktreten? Frau Nanahara hat offensichtlich große Schmerzen. Lassen Sie uns auf sie aufpassen."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Vous voulez bien reculer ? Visiblement, Dame Nanahara souffre énormément. Nous allons nous occuper d'elle."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
