L11_1 = "물러서라. 당주님께 손을 대는 자는 용서치 않겠다."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "下がれ。ご当主様に触れるものは容赦せぬ。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Stand back. Do not touch Lady Nanahara."
L10_1.m_Talk_ENG = L11_1
L11_1 = "退下！敢對堂主下手，休怪我手下不留情。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ถอยไปนะ อย่าได้มาแตะต้องนายฉัน"
L10_1.m_Talk_THA = L11_1
L11_1 = "Đứng lại. Đừng chạm vào Chủ Nhân của tôi."
L10_1.m_Talk_VTN = L11_1
L11_1 = "都滚开！如果谁敢碰家主，我绝不会手下留情！"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Treten Sie zurück. Und bitte berühren Sie Frau Nanahara nicht."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Pas un pas de plus. Laissez Dame Nanahara tranquille."
L10_1.m_Talk_FRA = L11_1
