L15_1.m_Pos = "C"
L16_1 = "무사님이 평소 즐기시는 찻잎에 티 나지 않게 섞어 넣었답니다."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "そなたが普段好んでいる茶葉にわからぬように混ぜておきました。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "I mixed some poison in with your tea leaves."
L15_1.m_Talk_ENG = L16_1
L16_1 = "我在你平時愛喝的茶裡，加了點毒藥。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ฉันใส่ยาพิษไปในใบชาของเธอน่ะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Tôi đã trộn một số chất độc vào lá trà của cô."
L15_1.m_Talk_VTN = L16_1
L16_1 = "我在你平时喜欢喝的茶水中，不动声色地掺了一点进去。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Ich habe etwas Gift in Ihren Tee gemischt."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Celui que j'ai mélangé à vos feuilles de thé..."
L15_1.m_Talk_FRA = L16_1
