L16_1.m_Talk_THA = L17_1
L17_1 = "Tôi hy vọng cô đã không uống nó với con gái của mình."
L16_1.m_Talk_VTN = L17_1
L17_1 = "哎呀，不知道你的女儿有没有喝下去呢？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Ich hoffe, Sie haben den Tee nicht mit Ihrer Tochter geteilt ... Oder?"
L16_1.m_Talk_DEU = L17_1
L17_1 = "J'espère que vous ne l'avez pas bu avec votre fille..."
L16_1.m_Talk_FRA = L17_1
