L29_1 = "NANAHARA_ACT4_STAGE3_END@78#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 78
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 3600406
L28_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L28_1.m_bWaitClick = true
