L29_1 = "KANADE_JAPAN_NULL_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L29_1 = "죄송합니다, 당주님."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "申し訳ございません、ご当主様。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "I’m sorry, Lady Nanahara."
L28_1.m_Talk_ENG = L29_1
L29_1 = "對不起，堂主。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ขอโทษด้วยค่ะ นายท่าน"
L28_1.m_Talk_THA = L29_1
L29_1 = "Tôi xin lỗi, Chủ Nhân."
L28_1.m_Talk_VTN = L29_1
L29_1 = "真是抱歉，家主。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Es tut mir leid, Frau Nanahara."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Je suis désolée, Dame Nanahara."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "NANAHARA_ACT4_STAGE3_END@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 3600406
L29_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "KANADE_JAPAN_NULL_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L30_1 = "당주님께서 제단으로 가려고 하셨을 때 제가 막지 않았다면, 적어도 이런 꼴은 당하시지 않았을 텐데……"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "当主様が祭壇に行かれようとした時に私が止めなかったら、\n少なくともこんな目にはあわなかったはず……"
L29_1.m_Talk_JPN = L30_1
L30_1 = "I shouldn’t have stopped you when you were going to the altar."
L29_1.m_Talk_ENG = L30_1
L30_1 = "堂主要去祭壇時，若不是我攔著您，也不會害您變成現在這樣…"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ฉันควรหยุดคุณตั้งแต่คุณไปที่แท่นบูชา"
L29_1.m_Talk_THA = L30_1
L30_1 = "Tôi không nên ngăn cô lại khi cô đến đền thờ."
L29_1.m_Talk_VTN = L30_1
L30_1 = "您在去祭坛的时候，如果我没有阻拦，至少不会是这样的结果……"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Ich hätte Sie nicht aufhalten sollen, als Sie zum Altar gingen."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Si je n'avais pas essayé de vous arrêter lorsque vous avez voulu vous rendre à l'autel, alors tout ceci ne serait jamais arrivé..."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
