L32_1 = "NANAHARA_ACT4_STAGE3_END@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3600406
L31_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "카나데……."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "かなで……"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Kanade..."
L31_1.m_Talk_ENG = L32_1
L32_1 = "速水奏……"
L31_1.m_Talk_TWN = L32_1
L32_1 = "คานาเดะ..."
L31_1.m_Talk_THA = L32_1
L32_1 = "Kanade..."
L31_1.m_Talk_VTN = L32_1
L32_1 = "奏……"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Kanade..."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Kanade..."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "NANAHARA_ACT4_STAGE3_END@82#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3600406
L32_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "실은 나도 알고 있었단다."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "実は私も知っていたのだ。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "I already knew..."
L32_1.m_Talk_ENG = L33_1
L33_1 = "其實我也很清楚。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ฉันรู้อยู่แล้ว..."
L32_1.m_Talk_THA = L33_1
L33_1 = "Tôi đã biết..."
L32_1.m_Talk_VTN = L33_1
L33_1 = "其实我也知道。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Ich wusste bereits ..."
L32_1.m_Talk_DEU = L33_1
L33_1 = "La vérité, c'est que je savais que les choses se passeraient ainsi."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "NANAHARA_ACT4_STAGE3_END@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3600406
L33_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "네가 제단으로 가는 날 막으러 올 것이라고 말이야."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "祭壇に向かう私を君が止めに来るということを。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "... that you were going to stop me from going to the altar."
L33_1.m_Talk_ENG = L34_1
L34_1 = "你會來攔著我，不讓我去祭壇。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "... ว่าเธอจะไปขวางไม่ให้ฉันไปที่แท่นบูชา"
L33_1.m_Talk_THA = L34_1
L34_1 = "... rằng cô sẽ ngăn tôi đến đền thờ."
L33_1.m_Talk_VTN = L34_1
L34_1 = "你会来阻止我去祭坛。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "... dass Sie mich davon abhalten würden, zum Altar zu gehen."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Je savais... que tu t'opposerais à ma décision."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "NANAHARA_ACT4_STAGE3_END@84#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 84
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3600406
L34_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "나도… 천총운검에 목숨을 바치는 걸 망설였어."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "私も……天叢雲剣に命を捧げることをためらっていた。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "I hesitated to sacrifice myself with Kusanagi."
L34_1.m_Talk_ENG = L35_1
L35_1 = "我其實…也很猶豫要把我的性命獻給天叢雲劍嗎？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ฉันลังเลที่จะสังเวยตัวเองด้วยคุซานางิ"
L34_1.m_Talk_THA = L35_1
L35_1 = "Tôi đã do dự trong việc hy sinh bản thân mình với Kusanagi."
L34_1.m_Talk_VTN = L35_1
L35_1 = "我也在犹豫……是否要用草薙剑献祭自己。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Ich zögerte, mich selbst mit dem Schwert Kusanagi zu opfern."
L34_1.m_Talk_DEU = L35_1
L35_1 = "À tel point que j'ai songé à me tuer moi-même, avec le Kusanagi."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "NANAHARA_ACT4_STAGE3_END@85#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 85
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 3600406
L35_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "너와 내 아이들과 작별해야 한다는 게 싫었어."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "君や私の子どもたちと別れなければならないのが嫌だった。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "I didn’t want to leave you and my children behind."
L35_1.m_Talk_ENG = L36_1
L36_1 = "因為我不想與你和我的孩子道別。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ฉันไม่อยากทิ้งเธอกับลูกๆ ไป"
L35_1.m_Talk_THA = L36_1
L36_1 = "Tôi không muốn bỏ lại cô và các con tôi."
L35_1.m_Talk_VTN = L36_1
L36_1 = "我真的不想和你，还有孩子们分开。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Ich wollte dich und meine Kinder nicht zurücklassen."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Mais je ne voulais pas vous laisser, mes enfants et toi, derrière moi..."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "NANAHARA_ACT4_STAGE3_END@86#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 86
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3600406
L36_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "그래서 함께 도망치고 싶었는데…"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "だから一緒に逃げたかったのだが……"
L36_1.m_Talk_JPN = L37_1
L37_1 = "So I wanted to run away with you..."
L36_1.m_Talk_ENG = L37_1
L37_1 = "所以原本打算要一起逃走…"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ฉันเลยอยากหนีไปกับเธอ..."
L36_1.m_Talk_THA = L37_1
L37_1 = "Vì vậy, tôi muốn chạy trốn với cô..."
L36_1.m_Talk_VTN = L37_1
L37_1 = "所以还想过一起逃走……"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Ich wollte mit dir weglaufen ..."
L36_1.m_Talk_DEU = L37_1
L37_1 = "J'ai donc pensé à m'enfuir..."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "NANAHARA_ACT4_STAGE3_END@87#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 87
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3600406
L37_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L38_1 = "더는 바람의 목소리가 길을 가르쳐주지 않더구나."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "これ以上は風の声が道を教えてくれなかった。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "But then the voice of wind stopped whispering to me."
L37_1.m_Talk_ENG = L38_1
L38_1 = "但風聲卻再不指引我方向。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "แต่แล้วสายลมก็หยุดกระซิบบอกฉัน"
L37_1.m_Talk_THA = L38_1
L38_1 = "Nhưng rồi gió thôi thì thầm với tôi."
L37_1.m_Talk_VTN = L38_1
L38_1 = "可是，风的声音不再指引我的道路。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Aber dann hörte die Stimme des Windes auf, mir zuzuflüstern."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Et c'est là que le vent a cessé de me murmurer son chant."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "NANAHARA_ACT4_STAGE3_END@88#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 88
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3600406
L38_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "결국 이렇게 됐지만… 난 널 원망하지 않아."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "結局こうなってしまったが……私は君を恨まない。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "It’s come down to this... but I don’t resent you."
L38_1.m_Talk_ENG = L39_1
L39_1 = "雖然結果是這樣…但我不恨你。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "มันกลายเป็นแบบนี้แล้ว... แต่ฉันก็ไม่ขุ่นเคืองเธอหรอกนะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Rồi thành ra thế này ... nhưng tôi không phẫn nộ gì với cô cả."
L38_1.m_Talk_VTN = L39_1
L39_1 = "虽然结果变成了这样……但我不会怨你。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Und jetzt sind wir hier ... aber ich nehme es Ihnen nicht übel."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Fais ce que tu as à faire... je ne t'en veux point."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "NANAHARA_ACT4_STAGE3_END@89#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 89
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3600406
L39_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "그러니… 마지막만큼은 내 부탁을 들어다오."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "だから……最期だけは私の頼みを聞いてくれ。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "So please... grant me my last wish..."
L39_1.m_Talk_ENG = L40_1
L40_1 = "所以…請你聽我最後的請求。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ดังนั้น... ช่วยทำให้ปรารถนาสุดท้ายของฉันเป็นจริงด้วยเถอะ..."
L39_1.m_Talk_THA = L40_1
L40_1 = "Vì vậy, xin vui lòng... ban cho tôi điều ước cuối cùng của tôi..."
L39_1.m_Talk_VTN = L40_1
L40_1 = "所以……能最后再拜托你一件事吗？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Also bitte... erfüllen Sie mir einen letzten Wunsch ..."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Alors s'il te plaît... accomplis ton devoir."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
