L48_1.m_Pos = "C"
L48_1.m_Crash = 20
L49_1 = "오로치님의 힘이 없으면 이 몸으론 얼마나 더 갈지도 모르는데, 잘도 이런 짓을……!"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "オロチ様の力がなければこの体がどれほど持つかわからないのに、\nよくもそんなことを……！"
L48_1.m_Talk_JPN = L49_1
L49_1 = "I don’t know how long I’ll last without Lord Orochi’s power... How dare you!"
L48_1.m_Talk_ENG = L49_1
L49_1 = "如果沒有大蛇的力量，我這個身體不知道還能撐到什麼時候，竟然……！"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ฉันไม่รู้หรอกนะว่าไม่มีพลังของท่านโอโรจิแล้วฉันจะอยู่ได้นานแค่ไหน... กล้าดียังไง!"
L48_1.m_Talk_THA = L49_1
L49_1 = "Tôi không biết mình sẽ tồn tại được bao lâu nếu không có sức mạnh của Chúa Tể Orochi ... Sao cô dám!"
L48_1.m_Talk_VTN = L49_1
L49_1 = "不，不！没有大蛇大人的力量，这具身体维持不了太久了。你竟敢做出这种事……！"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Ich weiß nicht, wie lange ich es ohne Orochis Macht noch aushalten kann ... Wie kannst du es wagen!"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Sans le pouvoir du Seigneur Orochi, comment vais-je survivre ? Petite insolente... !"
L48_1.m_Talk_FRA = L49_1
