L22_1 = "NANAHARA_ACT4_STAGE3_END@121#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 121
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 3600406
L21_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "ELDER_NPC_NANAHARA_PAST"
L21_1.m_CharStrID = L22_1
L22_1 = "크흠…… 이 정도면 확실하게 죽었군."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "ふむ……これなら間違いなく死んだな。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Ahem... She’s dead."
L21_1.m_Talk_ENG = L22_1
L22_1 = "咳咳……這樣應該是死了吧。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "อะแฮ่ม... เธอตายแล้วนะ"
L21_1.m_Talk_THA = L22_1
L22_1 = "Ahem... Cô ấy chết rồi."
L21_1.m_Talk_VTN = L22_1
L22_1 = "咳咳……这样应该死掉了吧。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Sie ... Sie ist bereits tot."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Ahem... Elle est bel et bien morte."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "NANAHARA_ACT4_STAGE3_END@122#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 122
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 3600406
L22_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "ELDER_NPC_NANAHARA_PAST"
L22_1.m_CharStrID = L23_1
L23_1 = "직계 무녀가 죽었으니, 자식이라도 바쳐야하나? 병약하긴 해도 일단은 무녀 혈통이니까……"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "直系の巫女が死んだし、その子どもでも捧げるべきか？\n病弱ではあるが一応巫女の血統だから……"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Since the priestess is gone now, maybe we should sacrifice her daughter. She is sickly, but she is of the same blood."
L22_1.m_Talk_ENG = L23_1
L23_1 = "既然直系巫女死了，那要獻她的後裔嗎？雖然體弱多病，但起碼是巫女的血統……"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ในเมื่อนักบวชหญิงจากไปแล้ว บางทีเราน่าจะสังเวยลูกสาวเธอซะนะ เธออาจจะป่วย แต่ก็มาจากสายเลือดเดียวกัน"
L22_1.m_Talk_THA = L23_1
L23_1 = "Vì bây giờ nữ tư tế đã mất, có lẽ chúng ta nên hy sinh con gái của bà ấy. Cô ta tuy ốm yếu nhưng cùng chung dòng máu."
L22_1.m_Talk_VTN = L23_1
L23_1 = "直系巫女死了，需要用她的后代进行献祭吗？虽然病弱，但至少是巫女的血脉……"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Da die Priesterin jetzt weg ist, sollten wir vielleicht auch ihre Tochter opfern. Sie kränkelt zwar etwas, aber sie ist vom selben Blut."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Puisque la prêtresse n'est plus, nous devrions peut-être sacrifier sa fille. Elle est fragile, certes, mais n'en partage pas moins le même sang que sa mère."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "NANAHARA_ACT4_STAGE3_END@123#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 123
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3600406
L23_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "UNIT_SERIOUS"
L23_1.m_Face = L24_1
L24_1 = "SAYO_NPC_NANAHARA_NULL"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "C"
L24_1 = "성급하게 굴면 인과가 뒤틀릴 뿐입니다. 때가 되면 오로치님께서 저에게 속삭이실 테니 기다리십시오."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "性急に行動しても因果が歪むだけです。\n時がくればオロチ様が私にささやいてくださるので、その時を待ちましょう。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Don’t rush. It will only bring more distortion to our destined future. Lord Orochi will speak to me when the time comes."
L23_1.m_Talk_ENG = L24_1
L24_1 = "欲速則不達，等時機成熟時大蛇跟我說的，請耐心等候。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "อย่ารีบร้อนไป มันมีแต่จะยิ่งทำให้อนาคตที่ลิตไว้แล้วของเราบิดผัน เมื่อถึงเวลาแล้วท่านโอโรจิจะบอกฉันเอง"
L23_1.m_Talk_THA = L24_1
L24_1 = "Đừng vội vàng. Nó sẽ chỉ mang lại nhiều biến dạng hơn cho tương lai đã định sẵn của chúng ta. Chúa Tể Orochi sẽ nói chuyện với tôi khi đến lúc."
L23_1.m_Talk_VTN = L24_1
L24_1 = "过于情急，只会让因果颠倒。到了合适的时候，大蛇大人会降下神谕的。我们还需要慢慢等待。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Keine Eile. Das wird nur noch mehr Veränderungen in unserer vorbestimmten Zukunft manifestieren. Orochi wird zu mir sprechen, wenn die Zeit gekommen ist."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Non, la précipitation n'apportera rien de bon. L'avenir est déjà écrit, et Seigneur Orochi me parlera le moment venu."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
