L26_1 = "NANAHARA_ACT4_STAGE3_END@125#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 125
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 3600406
L25_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "ELDER_NPC_NANAHARA_PAST"
L25_1.m_CharStrID = L26_1
L26_1 = "그렇다면 지금 당장은 오로치님을 깨우기 어렵겠군."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "ならば今すぐオロチ様を呼び起こすのは難しそうだな。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Well then, I suppose we can’t wake Lord Orochi for now."
L25_1.m_Talk_ENG = L26_1
L26_1 = "那現在應該無法喚醒大蛇。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ถ้าเช่นนั้น ผมก็คิดว่าตอนนี้เรายังปลุกท่านโอโรจิขึ้นมาไม่ได้"
L25_1.m_Talk_THA = L26_1
L26_1 = "Vậy thì, tôi cho rằng chúng ta không thể đánh thức Chúa Tể Orochi vào lúc này."
L25_1.m_Talk_VTN = L26_1
L26_1 = "那就是说，现在不能马上唤醒大蛇大人了。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Nun, ich nehme an, wir können Orochi vorerst nicht erwecken."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Alors nous devons abandonner l'idée de le réveiller, c'est ça ?"
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "NANAHARA_ACT4_STAGE3_END@126#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 126
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 3600406
L26_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "ELDER_NPC_NANAHARA_PAST"
L26_1.m_CharStrID = L27_1
L27_1 = "본부에는 뭐라고 둘러대야 하지?"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "本部には何と言い訳するのだ？"
L26_1.m_Talk_JPN = L27_1
L27_1 = "What do we tell headquarters?"
L26_1.m_Talk_ENG = L27_1
L27_1 = "該怎麼跟總部解釋才好呢？"
L26_1.m_Talk_TWN = L27_1
L27_1 = "เราจะรายงานศูนย์บัญชาการว่ายังไงดี?"
L26_1.m_Talk_THA = L27_1
L27_1 = "Chúng ta nói gì với trụ sở đây?"
L26_1.m_Talk_VTN = L27_1
L27_1 = "那该怎么和本部交代？"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Was sollen wir dem Hauptquartier nur sagen?"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Qu'allons nous dire au QG ?"
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "NANAHARA_ACT4_STAGE3_END@127#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 3600406
L27_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_Face = "UNIT_DESPAIR"
L28_1 = "SAYO_NPC_NANAHARA_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "C"
L28_1 = "보면 모르겠습니까? 이 호위 무사 년이 당주를 죽이고 도망친 겁니다."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "考えるまでもありません。この護衛が当主を殺して逃げたのです。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Can’t you see? The bodyguard killed Lady Nanahara and ran away."
L27_1.m_Talk_ENG = L28_1
L28_1 = "不是很明顯嗎？護衛武士殺了堂主後逃了。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ไม่เห็นรึไง? คนคุ้มกันฆ่าผู้นำตระกูลแล้วหนีไปนะสิ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Ông không thấy sao? Tên vệ sĩ đã giết chết tộc trưởng rồi bỏ chạy."
L27_1.m_Talk_VTN = L28_1
L28_1 = "还用说吗？当然是这个护卫武士杀掉家主后逃跑了。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Sind Sie tatsächlich so blind? Die Leibwächterin tötete Frau Nanahara und rannte davon."
L27_1.m_Talk_DEU = L28_1
L28_1 = "C'est pourtant évident, non ? Dame Nanahara a été assassinée par sa garde du corps, qui a ensuite pris la fuite."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
