L30_1 = "아아, 그렇지. 그렇게 되는 것이지."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "ああ、そうか。そういうことになるな。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Oh, yes, yes. That’s right."
L29_1.m_Talk_ENG = L30_1
L30_1 = "對對，沒錯，就是這麼回事。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "อ้อ ใช่ ใช่ จริงด้วย"
L29_1.m_Talk_THA = L30_1
L30_1 = "Ồ, ừ, ừ. Đúng thế."
L29_1.m_Talk_VTN = L30_1
L30_1 = "啊啊，没错。就是这样。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Oh, ja ja. Das ist richtig."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Ah, bien sûr. Le tableau est parfait."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
