L31_1 = "ELDER_NPC_NANAHARA_PAST"
L30_1.m_CharStrID = L31_1
L31_1 = "그럼 호위 무사는 어떻게 처리한다?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "では護衛の死体はどうする？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "What do we do with the dead bodyguard?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "那護衛武士要怎麼處理？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "แล้วเราจะทำยังไงกับคนคุ้มกันที่ตายไปล่ะ?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Chúng ta phải làm gì với tên vệ sĩ đã chết?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "那护卫武士该怎么处理？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Was machen wir mit dem Körper der Leibwächterin?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Mais qu'allons-nous faire du corps de Kanade ?"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "NANAHARA_ACT4_STAGE3_END@131#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3600406
