L32_1 = "UNIT_SERIOUS"
L31_1.m_Face = L32_1
L32_1 = "SAYO_NPC_NANAHARA_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "적당한 곳에 버리십시오."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "適当なところに捨ててください。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Bury her."
L31_1.m_Talk_ENG = L32_1
L32_1 = "找個適合的地方扔了。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ฝังซะสิ"
L31_1.m_Talk_THA = L32_1
L32_1 = "Chôn cô ta đi."
L31_1.m_Talk_VTN = L32_1
L32_1 = "随便扔到看不见的地方吧。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Begrabt sie."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Enterrez-la à l'abri des regards."
L31_1.m_Talk_FRA = L32_1
