L33_1 = "NANAHARA_ACT4_STAGE3_END@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3600406
L32_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "SAYO_NPC_NANAHARA_NULL"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "C"
L33_1 = "오로치님이 봉인된 산에 묻으면 충분할 겁니다."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "オロチ様が封印された山に埋めればいいでしょう。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Anywhere on this mountain where Lord Orochi is sealed."
L32_1.m_Talk_ENG = L33_1
L33_1 = "就埋在封印大蛇的山上裡吧！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ที่ไหนก็ได้บนเขาลูกนี้ที่ท่านโอโรจิถูกผนึกไว้"
L32_1.m_Talk_THA = L33_1
L33_1 = "Bất cứ nơi nào trên ngọn núi này, nơi Chúa Tể Orochi bị phong ấn."
L32_1.m_Talk_VTN = L33_1
L33_1 = "或者可以埋到大蛇大人被封印的山上。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Auf diesen Berg, wo Orochi versiegelt ist,"
L32_1.m_Talk_DEU = L33_1
L33_1 = "N'importe où fera l'affaire, sur cette montagne où Seigneur Orochi est scellé."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "NANAHARA_ACT4_STAGE3_END@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3600406
