L34_1 = "UNIT_LAUGH"
L33_1.m_Face = L34_1
L34_1 = "SAYO_NPC_NANAHARA_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "누구도 함부로 발길을 들이지 않는 곳이니까요."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "誰も安易に足を踏み入れない場所ですから。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "No one will dare come here."
L33_1.m_Talk_ENG = L34_1
L34_1 = "畢竟那個地方不是誰都可以靠近的。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ไม่มีใครกล้ามาที่นี่กันหรอก"
L33_1.m_Talk_THA = L34_1
L34_1 = "Sẽ không ai dám đến đây."
L33_1.m_Talk_VTN = L34_1
L34_1 = "毕竟不会有人轻易踏足那里。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "wird es nie jemand wagen."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Personne n'osera s'aventurer jusqu'ici."
L33_1.m_Talk_FRA = L34_1
