L36_1 = "SAYO_NPC_NANAHARA_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "그리고 당주께선, 돌아가기 전에 그 흉한 얼굴부터 가리는 편이 좋겠군요."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "それと当主は、戻る前にその酷い顔を隠したほうがよいでしょう。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "And I suggest you hide that scar on your face."
L35_1.m_Talk_ENG = L36_1
L36_1 = "還有，堂主回去前，最好先遮住你那張醜陋的臉。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "และขอแนะนำในให้ซ่อนแผลบนหน้านั่นซะด้วยนะ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Và tôi đề nghị ông nên giấu vết sẹo đó trên khuôn mặt của ông."
L35_1.m_Talk_VTN = L36_1
L36_1 = "还有你，回去之前，最好遮掩下你的脸。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Achso, und Sie sollten wahrscheinlich diese Narbe in Ihrem Gesicht verstecken."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Oh, et je vous suggère de cacher cette cicatrice sur votre visage."
L35_1.m_Talk_FRA = L36_1
