L38_1.m_Pos = "C"
L39_1 = "이건…… 하야미 카나데의 기억."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "これは……速水かなでの記憶。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "This is... Hayami Kanade’s memory."
L38_1.m_Talk_ENG = L39_1
L39_1 = "這是……速水奏的記憶。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "นี่คือ... ความทรงจำของฮายามิ คานาเดะ"
L38_1.m_Talk_THA = L39_1
L39_1 = "Đây là... ký ức của Hayami Kanade."
L38_1.m_Talk_VTN = L39_1
L39_1 = "这是……速水奏的记忆。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Das ist ... Hayami Kanades Erinnerung."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Ce sont... les souvenirs de Hayami Kanade."
