L41_1 = "NANAHARA_ACT4_STAGE3_END@140#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 3600406
L40_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L41_1 = "후후훗, 재미있는 물건을 찾았구나?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "ふふふ、面白いものを見つけたな？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Hah hah, you found an interesting toy."
L40_1.m_Talk_ENG = L41_1
L41_1 = "呵呵呵，你找到有趣的東西了？"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ฮ่าฮ่า เจอของเล่นน่าสนใจเข้าแล้วสิเจ้า"
L40_1.m_Talk_THA = L41_1
L41_1 = "Ha ha, ngươi đã tìm thấy một món đồ chơi thú vị."
L40_1.m_Talk_VTN = L41_1
L41_1 = "呵呵呵，找到了有趣的东西呢？"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Haha, da hast du ja ein interessantes Spielzeug gefunden!"
L40_1.m_Talk_DEU = L41_1
L41_1 = "Ha ha, tu as trouvé un jouet intéressant."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "NANAHARA_ACT4_STAGE3_END@141#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 3600406
L41_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_Face = "UNIT_PRIDE"
L41_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L41_1.m_Pos = "C"
L42_1 = "감상은 어떠니? 그것이 인간의 추악한 이기심이 낳은 참극이란다."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "どう思う？　それは人間の醜悪な利己主義が生んだ惨劇だ。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "What do you think? That was one of many tragedies that were born from humans' hideous desires."
L41_1.m_Talk_ENG = L42_1
L42_1 = "感想如何？這就是人類的自私釀成的悲劇。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "คิดว่าไงล่ะ? นั่นเป็นหนึ่งในหลายโศกนาฏกรรมที่เกิดขึ้นเพราะความปรารถนาอันน่ารังเกียจของมนุษย์เลยนะ"
L41_1.m_Talk_THA = L42_1
L42_1 = "Ngươi nghĩ sao? Đó là một trong nhiều bi kịch được sinh ra từ những ham muốn ghê tởm của con người."
L41_1.m_Talk_VTN = L42_1
L42_1 = "你有何感想？这就是因为人类自私自利的丑恶嘴脸所带来的惨剧。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Was denkst du? Das war doch eins zu eins eine von den vielen Tragödien, die aus den abscheulichen Begierden der Menschen entstanden sind, richtig?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Qu'en penses-tu ? Encore une énième tragédie, née de la cupidité sans limite des humains."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "NANAHARA_ACT4_STAGE3_END@142#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 3600406
L42_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L42_1.m_Pos = "C"
L43_1 = "넌 그런 모습을 보고도, 아직도 인간들을 위해 싸우고 싶은 거니?"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "貴様はそんなものを見ても、まだ人間のために戦いたいか？"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Do you still want to fight for humans, after watching this?"
L42_1.m_Talk_ENG = L43_1
L43_1 = "你看完還會想爲人類而戰嗎？"
L42_1.m_Talk_TWN = L43_1
L43_1 = "เห็นแล้วยังอยากสู้เพื่อมนุษย์อยู่รึเปล่าล่ะ?"
L42_1.m_Talk_THA = L43_1
L43_1 = "Ngươi có còn muốn chiến đấu cho nhân loại, sau khi xem nó không?"
L42_1.m_Talk_VTN = L43_1
L43_1 = "看到他们的样子后，还想为人类而战吗？"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Willst du immer noch für die Menschen kämpfen, nachdem du das gesehen hast?"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Même après avoir vu tout ça, tu veux continuer à te battre pour eux ?"
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
