L44_1 = "..."
L43_1.m_Talk_DEU = L44_1
L44_1 = "..."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "NANAHARA_ACT4_STAGE3_END@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 3600406
L44_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L44_1.m_Pos = "C"
L45_1 = "당신은…… 이 기억에서 비극과 인간의 추악한 면을 보았군요."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "あなたは……この記憶から悲劇と人間の醜悪さを見たのですね。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "You saw... a tragedy and the ugly side of us humans from this memory."
L44_1.m_Talk_ENG = L45_1
L45_1 = "你……在這段記憶中，看到的是悲劇和人性的醜惡一面。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "คุณเห็น... โศกนาฏกรรมและด้านที่อัปลักษณ์ของมนุษย์ในความทรงจำนี้"
L44_1.m_Talk_THA = L45_1
L45_1 = "Bà đã thấy... một bi kịch và mặt xấu xa của con người chúng tôi từ ký ức này."
L44_1.m_Talk_VTN = L45_1
L45_1 = "你……在奏的记忆中，只看到了悲剧和人类丑恶的一面。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Du hast in dieser Erinnerung ... eine Tragödie und die hässliche Seite von uns Menschen gesehen."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Une tragédie, la face sombre de l'humanité... voilà ce que vous avez choisi de voir dans cette affaire."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "NANAHARA_ACT4_STAGE3_END@145#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 145
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 3600406
L45_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L45_1.m_Pos = "C"
L46_1 = "하지만 인간에겐 그런 이기심만 있는 게 아닙니다."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "ですが、人間にはそのような利己主義しかないわけではありません。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "But we’re more than that."
L45_1.m_Talk_ENG = L46_1
L46_1 = "但人類並不是只有自私的一面。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "แต่เรามีอะไรมากกว่านั้นคะ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Nhưng chúng tôi còn hơn thế nữa."
L45_1.m_Talk_VTN = L46_1
L46_1 = "但人类不只有自私自利。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Aber wir sind mehr als nur das."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Mais nous autres humains, nous sommes bien plus que ça."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "NANAHARA_ACT4_STAGE3_END@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 3600406
L46_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_Face = "UNIT_IDLE"
L46_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L46_1.m_Pos = "C"
L47_1 = "전 이 기억으로부터 희망을 보았어요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "私はこの記憶から希望を見つけました。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "I saw a hope from this."
L46_1.m_Talk_ENG = L47_1
L47_1 = "我從這個記憶中看到的是希望。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ฉันเห็นความหวัง"
L46_1.m_Talk_THA = L47_1
L47_1 = "Tôi đã thấy một hy vọng từ điều này."
L46_1.m_Talk_VTN = L47_1
L47_1 = "我从这段记忆中，看到了希望。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Ich persönlich sah darin Hoffnung!"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Ce que j'ai vu dans ces souvenirs, moi, c'est un espoir."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
