L50_1 = "NANAHARA_ACT4_STAGE3_END@149#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 149
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 3600406
L49_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L49_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L49_1.m_Pos = "C"
L50_1 = "거기엔 배신과 술수 뿐이야."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "そこには裏切りと謀略があるだけだ。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "There was nothing but a betrayal and a scheme."
L49_1.m_Talk_ENG = L50_1
L50_1 = "裡面只有背叛和心機而已。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ไม่เห็นจะมีอะไรมากไปกว่าการทรยศและเล่ห์เพทุบาย"
L49_1.m_Talk_THA = L50_1
L50_1 = "Không có gì ngoài sự phản bội và âm mưu."
L49_1.m_Talk_VTN = L50_1
L50_1 = "那里只有名为背叛的恶臭而已！"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Ein Plan und ein Verrat – das waren die einzigen Elemente der Erinnerung."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Complot et trahison, il n'y a rien d'autre à y voir."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "NANAHARA_ACT4_STAGE3_END@150#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 150
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 3600406
L50_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L50_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L50_1.m_Pos = "C"
L51_1 = "무사는 당주를 빼돌리려다 결국 제 손으로 죽였고, 음모는 결국 밝혀지지 못했지."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "武士は当主を逃がそうとしたが結局自分の手で殺め、\n陰謀は最後まで明らかになることはなかった。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "The bodyguard tried to hide her Lady away, but had to kill her with her own hands; the scheme never came to light."
L50_1.m_Talk_ENG = L51_1
L51_1 = "武士帶走堂主後，結果還是親手殺掉堂主，詭計也始終無法揭穿。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "คนคุ้มกันพยายามพาเจ้านายไปซ่อน แต่กลับต้องฆ่าเธอด้วยมือตัวเอง เล่ห์ลวงของวายร้ายที่ไม่เคยถูกเปิดเผย"
L50_1.m_Talk_THA = L51_1
L51_1 = "Người vệ sĩ cố gắng giấu Chủ Nhân của cô ấy đi, nhưng phải giết cô ấy bằng chính đôi tay mình; kế hoạch của những kẻ phản diện không bao giờ được đưa ra ánh sáng."
L50_1.m_Talk_VTN = L51_1
L51_1 = "武士想要救出家主，却只能亲手杀掉了她。最终也没能揭发阴谋。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Die Leibwächterin versuchte erst, die Anführerin zu retten. Dann blieb ihr nichts anderes übrig, als sie mit ihren eigenen Händen zu töten. Der Plan ist also nicht aufgegangen."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Kanade a essayé de soustraire sa Dame à ses ennemis, mais elle a finalement dû la tuer de ses propres mains. Et le complot, lui, n'a jamais éclaté au grand jour."
L50_1.m_Talk_FRA = L51_1
