L2_1 = "NANAHARA_ACT4_STAGE3_END@151#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 151
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 3600406
L1_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L1_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L1_1.m_Pos = "C"
L2_1 = "게다가 이 모든 사건을 일으킨 녀석은 마지막 순간 날 저주하면서 죽었단다."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "しかも、この一連の事件を起こしたやつは、\n最期の瞬間に私を呪いながら死んだのだ。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "And the culprit behind all this died, cursing my name."
L1_1.m_Talk_ENG = L2_1
L2_1 = "而惹出這一切事端的傢伙，臨死前還在詛咒我。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "และคนร้ายที่อยู่เบื้องหลังการตายทั้งหมดนี้ ก่นด่านามข้า"
L1_1.m_Talk_THA = L2_1
L2_1 = "Và thủ phạm đằng sau tất cả những điều này đã chết, trong khi không ngừng nguyền rủa tên ta."
L1_1.m_Talk_VTN = L2_1
L2_1 = "而最后，导致这一切发生的家伙，临死前还在怨毒地诅咒我。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Und die Schuldige hinter all dem starb und verfluchte meinen Namen."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Pire, celle qui était derrière tout ça est désormais morte en maudissant mon nom."
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "NANAHARA_ACT4_STAGE3_END@152#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 152
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 3600406
L2_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L2_1.m_Pos = "C"
L3_1 = "그 안에 희망 같은 건 없어."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "その中に希望などない。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "There is no hope in this."
L2_1.m_Talk_ENG = L3_1
L3_1 = "那裡面沒有希望。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ไม่เห็นในนี้จะมีความหวังอันใด"
L2_1.m_Talk_THA = L3_1
L3_1 = "Không có hy vọng gì vào điều này."
L2_1.m_Talk_VTN = L3_1
L3_1 = "这里面没有任何希望。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Das hört sich nicht sehr nach Hoffnung an!"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Et tu me parles d'espoir ?"
L2_1.m_Talk_FRA = L3_1
