L6_1.m_Pos = "C"
L7_1 = "하야미 가문은…… 배신을 하지 않았어요."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "速水家は……裏切りをしませんでした。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Hayami never faltered."
L6_1.m_Talk_ENG = L7_1
L7_1 = "速水家族……不是叛徒。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ฮายามิไม่เคยหวั่นไหว"
L6_1.m_Talk_THA = L7_1
L7_1 = "Hayami không bao giờ chùn bước."
L6_1.m_Talk_VTN = L7_1
L7_1 = "速水家族……没有背叛。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Hayami geriet nie ins Wanken."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Car la volonté d'Hayami n'a jamais faibli."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "NANAHARA_ACT4_STAGE3_END@157#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 157
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 3600406
L7_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L7_1.m_Pos = "C"
L8_1 = "끝까지, 소중한 사람을 위해 굴하지 않고 저항했죠."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "最後まで、大切な人のために屈せず抵抗しました。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "She fought until the end to protect someone she cared for."
L7_1.m_Talk_ENG = L8_1
L8_1 = "她直到最後都沒有屈服，誓死抵抗要保護最在意的人。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "เธอต่อสู้จนวาระสุดท้ายเพื่อปกป้องคนที่ตัวเองใส่ใจ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Bà ấy đã chiến đấu cho đến cùng để bảo vệ người mà bà ấy chăm sóc."
L7_1.m_Talk_VTN = L8_1
L8_1 = "他们为了珍视的人，到最后都没有屈服，一直在抵抗。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Sie hat bis zum Schluss gekämpft, um jemanden zu beschützen, die ihr wichtig war."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Elle s'est battue jusqu'au bout pour protéger un être qui lui était cher."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "NANAHARA_ACT4_STAGE3_END@158#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 158
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 3600406
L8_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_IDLE"
L8_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L8_1.m_Pos = "C"
L9_1 = "무녀와 호위 무사."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "巫女と護衛。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "The priestess and the bodyguard."
L8_1.m_Talk_ENG = L9_1
L9_1 = "巫女和護衛武士，"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ทั้งนักบวชหญิงและคนคุ้มกัน"
L8_1.m_Talk_THA = L9_1
L9_1 = "Nữ tư tế và vệ sĩ."
L8_1.m_Talk_VTN = L9_1
L9_1 = "巫女与护卫武士。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Die Priesterin und die Leibwächterin."
L8_1.m_Talk_DEU = L9_1
L9_1 = "La prêtresse, et sa garde du corps..."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "NANAHARA_ACT4_STAGE3_END@159#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 159
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 3600406
L9_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Face = "UNIT_IDLE"
L9_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L9_1.m_Pos = "C"
L10_1 = "두 사람은 마지막까지 인간으로서의 긍지를 잃지 않았던 겁니다."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "二人は最後まで、人間としての誇りを失わなかったのです。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "They never lost their human dignity until the very last moment."
L9_1.m_Talk_ENG = L10_1
L10_1 = "她們直到最後一刻，都沒有失去身為一個人的驕傲。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ทั้งสองรักษาศักดิ์ศรีความเป็นมนุษย์ไว้ได้อย่างสง่างามจนวาระสุดท้าย"
L9_1.m_Talk_THA = L10_1
L10_1 = "Họ không bao giờ đánh mất phẩm giá con người của mình cho đến giây phút cuối cùng."
L9_1.m_Talk_VTN = L10_1
L10_1 = "她们两个人临终前也没丢掉人类的自尊。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Sie haben bis zum letzten Moment ihre Menschenwürde nicht verloren."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Jusque dans leurs derniers instants, elles ont gardé leur dignité."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "NANAHARA_ACT4_STAGE3_END@160#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 3600406
L10_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_HATE"
L10_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L10_1.m_Pos = "C"
L11_1 = "너희가 말하는 긍지가 고작 죽음이라니, 딱하구나."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "貴様らの言う誇りがただの死だとは気の毒だな。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "You find dignity in death. What a pity."
L10_1.m_Talk_ENG = L11_1
L11_1 = "驕傲的結果就是死，真可憐。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "เจ้าเห็นศักดิ์ศรีในความตายสินะ น่าสมเพชจริง"
L10_1.m_Talk_THA = L11_1
L11_1 = "Ngươi tìm thấy phẩm giá trong cái chết. Thật đáng tiếc."
L10_1.m_Talk_VTN = L11_1
L11_1 = "如果你们说的自尊是以死亡为代价的话，那真是可怜。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Leute wie du finden Würde eh erst im Tod. Welche Schande."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Une dignité qu'elles auront apporté dans l'au-delà. Quel dommage."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
