L13_1 = "NANAHARA_ACT4_STAGE3_END@162#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 162
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 3600406
L12_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L12_1.m_Pos = "C"
L13_1 = "네가 원한 것이 그런 것이라면, 그 긍지를 이룰 수 있도록 내가 거들어주마."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "貴様の望みがそれであれば、その誇りを守れるように我が手伝ってやろう。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "If that’s what you wish, I’ll grant you the dignity."
L12_1.m_Talk_ENG = L13_1
L13_1 = "若那是你想要的，我就成全你的驕傲吧！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "หากปรารถนาเช่นนั้น ข้าก็จะมอบศักดิ์ศรีให้เจ้า"
L12_1.m_Talk_THA = L13_1
L13_1 = "Nếu đó là điều ngươi muốn, ta sẽ ban cho ngươi phẩm giá."
L12_1.m_Talk_VTN = L13_1
L13_1 = "如果这是你们想要的，那我成全你们的自尊。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Wenn du dir das wünscht, werde ich dir diesen Wunsch gewähren."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Si c'est que tu souhaites, je vais te donner une chance de faire briller la tienne, de dignité."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
