L14_1 = "都結束了！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "มาจบๆ กันไปให้หมดซะที!"
L13_1.m_Talk_THA = L14_1
L14_1 = "Hãy kết thúc tất cả!"
