L17_1 = "흥, 귀찮군. 아직도 막아낼 기운이……?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "ふん、面倒だな。まだ防げる力が……？"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Hmpf, how bothersome. You still have the power to fight back..."
L16_1.m_Talk_ENG = L17_1
L17_1 = "哼，真煩！還沒放棄抵抗嗎……？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ฮึ่ม น่ารำคาญเสียจริง เจ้ายังเหลือพลังจะสู้อยู่อีก..."
L16_1.m_Talk_THA = L17_1
L17_1 = "Hừm, thật khó chịu. Ngươi vẫn có sức mạnh để chống lại..."
L16_1.m_Talk_VTN = L17_1
L17_1 = "哼，真麻烦。竟然还有力气抵挡……？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Hmpf, wie lästig. Du hast nach all dem immer noch die Kraft, dich zu wehren?"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Hmpf, tu parles de gêneurs... Je suis surprise de voir que vous pouvez encore vous battre..."
L16_1.m_Talk_FRA = L17_1
