L24_1 = "NANAHARA_ACT4_STAGE3_END@173#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 173
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3600406
L23_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L24_1 = "너 같은 평범한 인간이 어째서……"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "貴様のような平凡な人間がなぜ……"
L23_1.m_Talk_JPN = L24_1
L24_1 = "You’re just a human..."
L23_1.m_Talk_ENG = L24_1
L24_1 = "像你這種平凡的人……"
L23_1.m_Talk_TWN = L24_1
L24_1 = "เจ้าเป็นแค่มนุษย์..."
L23_1.m_Talk_THA = L24_1
L24_1 = "Ngươi chỉ là một con người..."
L23_1.m_Talk_VTN = L24_1
L24_1 = "你这样平凡的人类……"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Du bist nur ein Mensch ..."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Tu n'es qu'un humaine, et pourtant..."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "NANAHARA_ACT4_STAGE3_END@174#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 174
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 3600406
L24_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L25_1 = "천총운검의 신력을 발현할 수 있는 거지?!"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "天叢雲剣の神力を発現できる！？"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Yet you’re using the power of Kusanagi?!"
L24_1.m_Talk_ENG = L25_1
L25_1 = "怎麼可能發現天叢雲劍的神力？！"
L24_1.m_Talk_TWN = L25_1
L25_1 = "แต่กลับใช้พลังของคุซานางิได้หรือนี่?!"
L24_1.m_Talk_THA = L25_1
L25_1 = "Sao ngươi lại đang sử dụng sức mạnh của Kusanagi được?!"
L24_1.m_Talk_VTN = L25_1
L25_1 = "怎么能发挥出草薙剑的神力？！"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Und doch nutzt du die Kraft von Kusanagi?!"
L24_1.m_Talk_DEU = L25_1
L25_1 = "Tu peux utiliser le pouvoir du Kusanagi ?"
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
