L27_1 = "NANAHARA_ACT4_STAGE3_END@176#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 3600406
L26_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L27_1 = "오로치여."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "オロチよ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Orochi."
L26_1.m_Talk_ENG = L27_1
L27_1 = "大蛇。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "โอโรจิ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Orochi."
L26_1.m_Talk_VTN = L27_1
L27_1 = "大蛇！"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Orochi!"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Orochi."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "NANAHARA_ACT4_STAGE3_END@177#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 177
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 3600406
L27_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L28_1 = "저는, 바람이 들려주었던 미래가 마지막 희망이라고 생각했습니다."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "私は、風が聞かせてくれた未来が最後の希望だと思っていました。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "When I heard the future that the wind whispered to me, I thought it was the only hope we had."
L27_1.m_Talk_ENG = L28_1
L28_1 = "我以前認爲風聲告訴我的的未來是最後的希望。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ตอนฉันได้ยินอนาคตที่สายลมกระซิบบอก ฉันก็นึกว่าเป็นความหวังเดียวที่ตัวเองมีค่ะ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Khi tôi nghe tương lai mà gió thì thầm với tôi, tôi nghĩ rằng đó là hy vọng duy nhất của chúng tôi."
L27_1.m_Talk_VTN = L28_1
L28_1 = "我一直认为，风告诉我的未来就是最后的希望。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Als ich die Zukunft, die mir der Wind zuflüsterte, hörte, dachte ich, dies sei unsere einzige Hoffnung."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Quand j'ai entendu l'avenir que le vent m'a murmuré, j'ai pensé que c'était la seule issue qui s'offrait à nous."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "NANAHARA_ACT4_STAGE3_END@178#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 178
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 3600406
L28_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L29_1 = "하지만 지금은 알고 있어요."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "ですが、今は知っています。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "But now I know."
L28_1.m_Talk_ENG = L29_1
L29_1 = "但我現在知道，"
L28_1.m_Talk_TWN = L29_1
L29_1 = "แต่ตอนนี้ฉันรู้แล้ว"
L28_1.m_Talk_THA = L29_1
L29_1 = "Nhưng bây giờ tôi đã biết."
L28_1.m_Talk_VTN = L29_1
L29_1 = "但现在我才知道，"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Aber jetzt habe ich alles verstanden."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Mais maintenant, j'ai enfin compris."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "NANAHARA_ACT4_STAGE3_END@179#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 179
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 3600406
L29_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L30_1 = "바람은 방향만을 가르쳐 줄 뿐, 때로 우리는 그 바람을 거슬러야 할 때도 있다는 것을요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "風は方向だけを告げてくれるだけで、時に私たちはその風に\n逆らわなければならない時もあるということを。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "The wind only gives me direction; sometimes I have to go against it."
L29_1.m_Talk_ENG = L30_1
L30_1 = "風只能指引方向，有時我們也需要逆風而行。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "สายลมเพียงนำทางฉัน และบางครั้งฉันก็ต้องไปทางอื่น"
L29_1.m_Talk_THA = L30_1
L30_1 = "Gió chỉ cho tôi phương hướng; đôi khi tôi phải làm ngược lại nó."
L29_1.m_Talk_VTN = L30_1
L30_1 = "风指引的从来都只是方向，有时候我们需要逆风而行。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Der Wind empfiehlt uns nur eine Richtung. Wir haben immer die Wahl, ihm nicht zu folgen."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Le vent... m'indique seulement la direction. Et parfois, je dois m'y opposer."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "NANAHARA_ACT4_STAGE3_END@180#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 180
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 3600406
L30_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L31_1 = "그대는 상처받았습니다."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "貴方は傷ついたのでしょう。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "You were hurt by humans."
L30_1.m_Talk_ENG = L31_1
L31_1 = "你受傷了。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "คุณเคยถูกมนุษย์ทำร้ายเอาสินะคะ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Bà đã bị nhân loại tổn thương."
L30_1.m_Talk_VTN = L31_1
L31_1 = "你受到了伤害。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Du wurdest von Menschen verletzt."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Les humains vous ont blessé."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "NANAHARA_ACT4_STAGE3_END@181#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 181
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3600406
L31_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L32_1 = "믿었던 인간들의 욕망에, 신뢰의 배반에 좌절했겠죠."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "信じていた人間の欲望に、信頼への裏切りに絶望したのでしょう。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "You trusted them, but they betrayed you due to their selfish desires."
L31_1.m_Talk_ENG = L32_1
L32_1 = "因為人類的慾望和背叛而受挫。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "คุณไว้ใจพวกเขา แต่พวกเขากลับหักหลังคุณเพราะความปรารถนาอันเห็นแก่ตัวของตน"
L31_1.m_Talk_THA = L32_1
L32_1 = "Bà đã tin tưởng họ, nhưng họ đã phản bội bà do những ham muốn ích kỷ của họ."
L31_1.m_Talk_VTN = L32_1
L32_1 = "被信任着的人所背叛而感到挫折。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Du hast ihnen vertraut, aber sie haben dich aufgrund ihrer selbstsüchtigen Wünsche betrogen."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Vous leur avez accordé votre confiance, et ils l'ont trahi à cause de leurs désirs égoïstes."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "NANAHARA_ACT4_STAGE3_END@182#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3600406
L32_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L33_1 = "그런 그대가 무녀의 몸을 취한 뒤, 바람의 목소리로부터 어떤 미래를 들었는지는 모르겠지만,"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "そんな貴方が巫女の身体を手に入れた後、\n風の声からどのような未来を聞いたのかはわかりませんが。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "I don’t know what you heard from the voice of wind after you took over the priestess’s body."
L32_1.m_Talk_ENG = L33_1
L33_1 = "雖然我不知道你奪取巫女的身體後，從風聲中聽到什麼樣的未來，"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ฉันไม่รู้นะคะว่ายึดร่างนักบวชหญิงมาแล้วคุณได้ยินอะไรจากสายลม"
L32_1.m_Talk_THA = L33_1
L33_1 = "Tôi không biết bà đã nghe thấy những gì từ gió sau khi chiếm lấy cơ thể của nữ tư tế."
L32_1.m_Talk_VTN = L33_1
L33_1 = "我不知道夺取巫女身体后的你，从风的声音中听到了什么样的未来，"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Ich weiß nicht, was du von der Stimme des Windes gehört hast, nachdem du den Körper der Priesterin übernommen hast."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Je ne sais pas ce que vous a murmuré le vent quand vous avez récupéré le corps de la prêtresse..."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "NANAHARA_ACT4_STAGE3_END@183#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3600406
L33_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L34_1 = "저는 더 이상 바람의 목소리에만 기대지 않겠습니다."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "私はこれ以上、風の声だけを頼りにすることはしません。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "But I will no longer lean on the voice of wind."
L33_1.m_Talk_ENG = L34_1
L34_1 = "但我決定不再依靠風聲。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "แต่ฉันจะไม่เอาแต่พึ่งพาเสียงของสายลมแล้วค่ะ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Nhưng tôi sẽ không còn dựa vào tiếng gió nữa."
L33_1.m_Talk_VTN = L34_1
L34_1 = "但我决定不再继续依靠风的声音。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Aber ich ... Ich werde mich nicht länger auf die Stimme des Windes stützen."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Mais pour ma part, je ne me fierai plus à ce qu'il me dit."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "NANAHARA_ACT4_STAGE3_END@184#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 184
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3600406
L34_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L35_1 = "인간을 지켜야 할 존재가 인간을 능멸하는 순간, 그대의 역할은 끝난 것입니다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "人間を守るべき存在が人間を軽蔑した時、貴方の役割は終わったのです。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "You were supposed to protect humans. When you decided to go against humans, you lost your place in this world."
L34_1.m_Talk_ENG = L35_1
L35_1 = "你原本是該守護人類的，但在你輕蔑人類的瞬間，你便已經失去作用。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "คุณควรจะปกป้องมนุษย์นะคะ เพราะพอคุณตัดสินใจจะอยู่คนละฝ่ายกับมนุษย์ โลกนี้ก็ไม่มีที่ให้คุณอยู่แล้ว"
L34_1.m_Talk_THA = L35_1
L35_1 = "Bà  đáng lẽ phải bảo vệ nhân loại. Khi bà quyết định chống lại loài người, bà đã đánh mất vị trí của mình trên thế giới này."
L34_1.m_Talk_VTN = L35_1
L35_1 = "当守护人类的存在，开始凌侮人类的时候，你的职责就已经结束。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Du solltest Menschen schützen, das war deine Gabe! Als du dich entschieden hast, gegen die Menschen vorzugehen, hast du deinen Platz in dieser Welt verloren."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Vous qui deviez protéger les humains, vous avez décidé de vous retourner contre eux. De fait, vous n'avez plus votre place en ce monde."
