L44_1 = "이럴 수가…… 전혀 통하지 않는다고?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "なんだと……まったく通じない？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "No way... It doesn’t work at all?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "怎麼可能……完全無效？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "เป็นไปไม่ได้... มันไมไ่ด้ผลเลยหรือนี่?"
L43_1.m_Talk_THA = L44_1
L44_1 = "Không thể nào... Nó không hiệu quả chút nào sao?"
L43_1.m_Talk_VTN = L44_1
L44_1 = "怎么可能……完全不起作用？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Wie? Was? ... Es funktioniert auf einmal gar nicht mehr ...?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Impossible... Mes attaques ne fonctionnent pas ?"
L43_1.m_Talk_FRA = L44_1
