L44_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L45_1 = "두려워 마십시오. 그대는 단지 태고의 존재로 돌아갈 뿐입니다."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "怖がらないでください。貴方はただ、太古の存在に戻るだけです。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Don’t be afraid. You will only return to your original form."
L44_1.m_Talk_ENG = L45_1
L45_1 = "不要害怕，你只是打回原形而已。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "อย่ากลัวไปเลยค่ะ คุณก็แค่กลับสู่ร่างเดิมเท่านั้น"
L44_1.m_Talk_THA = L45_1
L45_1 = "Đừng sợ. Bà sẽ chỉ trở lại hình thức ban đầu thôi."
L44_1.m_Talk_VTN = L45_1
L45_1 = "别太担心。你只会重新回归为太古的存在而已。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Keine Angst. Du kehrst nur zu deiner ursprünglichen Form zurück!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "N'ayez pas peur. Vous reviendrez simplement à votre forme d'origine."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
