L45_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L46_1 = "세상이 그대를 필요로 한다면, 먼 훗날 다시 깨어나게 되겠지요."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "世界が貴方を必要とするならば、いつかまた目覚めることになるでしょう。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "When the world calls upon you, you will come back."
L45_1.m_Talk_ENG = L46_1
L46_1 = "如果世界需要你，在遙遠的未來你便會甦醒。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "เมื่อโลกเรียกหา คุณก็จะกลับมาอีก"
L45_1.m_Talk_THA = L46_1
L46_1 = "Khi thế giới kêu gọi, bà sẽ trở lại."
L45_1.m_Talk_VTN = L46_1
L46_1 = "如果世界需要你，在很久以后，你可能还会重新苏醒。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Wenn die Welt dich ruft, wirst du zurückkommen."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Quand le monde aura de nouveau besoin de vous, vous reviendrez."
L45_1.m_Talk_FRA = L46_1
