L15_1 = "NANAHARA_ACT4_STAGE3_END@214#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 214
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 3600406
L14_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Face = "UNIT_IDLE"
L15_1 = "ZENZIROU_NANA_NULL_NULL"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "C"
L15_1 = "그, 그러게. 눈앞이 번쩍하면서 끝난 줄 알았는데, 지금은 한숨 잔 것처럼 멀쩡해."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "そ、そうだな。目の前が光ってこれで終わりかと思ったけど、\n今はたっぷり寝た後みたいに元気だ。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Yeah, I thought I was dead when I saw the lightning in front of my eyes. But now I feel so refreshed."
L14_1.m_Talk_ENG = L15_1
L15_1 = "對啊，我眼前閃過那道光的時候，我以為我死定了，現在感覺好像只是睡了一覺一樣。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ใช่ แต่ตอนเห็นแสงตรงหน้านั่นนึกว่าจะเดี้ยงไปแล้วซะอีก แต่ตอนนี้สดชื่นมากเลย"
L14_1.m_Talk_THA = L15_1
L15_1 = "Ừ, tôi tưởng như mình đã chết khi nhìn thấy tia chớp trước mắt. Nhưng bây giờ tôi cảm thấy rất sảng khoái."
L14_1.m_Talk_VTN = L15_1
L15_1 = "是、是啊。原本我都以为要完蛋了。但现在感觉，就像是睡了一觉一样。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Ja, ich dachte, ich wäre tot, als ich den Blitz vor meinen Augen sah. Aber jetzt fühle ich mich wie ... neugeboren."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Ouais. J'ai bien cru que c'était la fin quand j'ai vu cet éclair défiler devant mes yeux, mais.... je me sens plutôt bien, en fait."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "NANAHARA_ACT4_STAGE3_END@215#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 215
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 3600406
L15_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_IDLE"
L15_1.m_CharStrID = "CHIFUYU_NANA_NULL_NULL"
L15_1.m_Pos = "C"
L16_1 = "제가 입었던 상처도…… 아물었군요."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "私が負った傷も……治っています。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "My wounds are all healed, too."
L15_1.m_Talk_ENG = L16_1
L16_1 = "我受的傷……也癒合了。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "แผลของฉันก็หายไปหมดด้วยค่ะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Vết thương của tôi cũng đã lành."
L15_1.m_Talk_VTN = L16_1
L16_1 = "我身上的伤……也全都愈合了。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Meine Wunden sind auch alle verheilt."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Mes blessures aussi... elles ont complètement guéri."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "NANAHARA_ACT4_STAGE3_END@216#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 216
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 3600406
L16_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L16_1.m_bWaitClick = true
