L16_1.m_Pos = "C"
L17_1 = "아니, 오히려 이전보다 더 강해진 느낌입니다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "いいえ、むしろ以前よりも力が増した気がします。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "I even feel stronger than before."
L16_1.m_Talk_ENG = L17_1
L17_1 = "不，感覺似乎比以前更強。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "รู้สึกแข็งแรงขึ้นกว่าเดิมด้วยซ้ำ"
L16_1.m_Talk_THA = L17_1
L17_1 = "Tôi thậm chí còn cảm thấy mạnh mẽ hơn trước."
L16_1.m_Talk_VTN = L17_1
L17_1 = "不，甚至比以前更加健康。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Ich fühle mich sogar stärker als zuvor."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Je me sens bien plus forte qu'avant..."
L16_1.m_Talk_FRA = L17_1
