L22_1 = "NANAHARA_ACT4_STAGE3_END@221#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 221
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 3600406
L21_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L21_1.m_Pos = "C"
L22_1 = "기껏 얻어낸 신력으로 무얼 하려나 했더니…"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "せっかく得た神力で何をするかと思えば……"
L21_1.m_Talk_JPN = L22_1
L22_1 = "I was wondering what you were going to do with the divine power you gained..."
L21_1.m_Talk_ENG = L22_1
L22_1 = "我還想你會用好不容易得到的神力做什麼…"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ข้ารึก็สงสัยว่าเจ้าจะทำอะไรกับพลังเทวะที่ได้ไป..."
L21_1.m_Talk_THA = L22_1
L22_1 = "Ta đang tự hỏi ngươi sẽ làm gì với sức mạnh thần thánh mà ngươi có được..."
L21_1.m_Talk_VTN = L22_1
L22_1 = "我还以为你要用获得的神力做些什么……"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Ich habe mich gefragt, was du mit der gewonnenen göttlichen Kraft machen würdest ..."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Je me demandais ce que tu allais faire de tes pouvoirs divins nouvellement acquis..."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "NANAHARA_ACT4_STAGE3_END@222#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 222
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 3600406
L22_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L22_1.m_Pos = "C"
L22_1.m_Crash = 20
L23_1 = "고작 이깟 미물들을 살려내는데 신력을 쏟아부었다고?"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "こんな虫けら同然の人間どもを生かすために神力を注ぎ込んだだと？"
L22_1.m_Talk_JPN = L23_1
L23_1 = "And you used it to save these insignificant critters?"
L22_1.m_Talk_ENG = L23_1
L23_1 = "結果是把神力全部用在救他們嗎？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "แล้วเจ้าก็เอาไปช่วยพวกหนอนแมลงที่ไม่มีความสลักสำคัญเนี่ยนะ?"
L22_1.m_Talk_THA = L23_1
L23_1 = "Và ngươi đã sử dụng nó để cứu những sinh vật nhỏ bé này ư?"
L22_1.m_Talk_VTN = L23_1
L23_1 = "原来是将神力浪费在这些微不足道的人身上了？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Und du verschwendest sie, um diesen Berg vor Abschaum zu retten? Schäm dich!"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Mais tu n'as rien trouvé de mieux que de sauver ces misérables insectes ?"
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "NANAHARA_ACT4_STAGE3_END@223#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 223
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 3600406
L23_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L23_1.m_Pos = "C"
L24_1 = "후훗, 자신의 목숨까지 바치려 했던 무녀가 이런 어리석은 선택을 할 줄이야."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "ふふっ、己の命まで捧げようとした巫女が、こうも愚かな選択をするとは。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Hah hah, who would have known that the priestess who was willing to sacrifice her own life would make such a foolish choice?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "呵呵，沒想到原本想獻出自己生命的巫女，會做出這種愚昧的選擇。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ฮ่าฮ่า ใครจะไปคิดว่านักบวชหญิงีท่ยินดีสละชีวิตตัวเองจะเลือกอะไรโง่ๆ แบบนี้?"
L23_1.m_Talk_THA = L24_1
L24_1 = "Ha ha, ai mà biết được rằng nữ tư tế sẵn sàng hy sinh mạng sống của mình lại có một lựa chọn ngu xuẩn như vậy chứ?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "呵哈哈哈哈。不惜献祭自己生命的巫女，竟然也会做出这么愚蠢的选择。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Hahaha, wer hätte gedacht, dass die Priesterin, die erst bereit war, ihr eigenes Leben zu opfern, eine so naive Entscheidung treffen würde?"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Hu hu. Qui aurait pu prédire qu'une prêtresse décidée à sacrifier sa propre vie ferait un choix aussi insensé ?"
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
