L26_1 = "아니. 치나츠는 잘못된 선택을 하지 않았어."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "いや、千夏は選択を間違えてなんかない。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "No, Chinatsu made the right choice."
L25_1.m_Talk_ENG = L26_1
L26_1 = "不，千夏沒有做出錯誤的選擇。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ไม่นะ ชินัตสึเลือกทางที่ถูกแล้ว"
L25_1.m_Talk_THA = L26_1
L26_1 = "Không, Chinatsu đã lựa chọn đúng."
L25_1.m_Talk_VTN = L26_1
L26_1 = "不，千夏的选择没有错。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Falsch. Sie hat genau das Richtige getan!"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Non, Chinatsu a fait le bon choix."
L25_1.m_Talk_FRA = L26_1
