L31_1 = "FX_COMBAT_ALL_MAGIC_SPELL_09"
L30_1.m_StartFXSoundName = L31_1
L31_1 = "MINATO_NANA_NULL_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "내가 쓰러뜨리기로. 약속했으니까!"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "僕が倒すと、約束したから！"
L30_1.m_Talk_JPN = L31_1
L31_1 = "I promised her that I would slay you!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "打倒你！打勾勾！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ผมสัญญากับเธอไว้ว่าจะฆ่าแกไงล่ะ!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tôi đã hứa với cô ấy rằng tôi sẽ giết bà!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "将被我们打败。这是我们的约定！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ich ihr versprochen habe, dich für sie umzubringen!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Je lui ai promis que je te tuerais !"
L30_1.m_Talk_FRA = L31_1
