L34_1 = "UNIT_SERIOUS"
L33_1.m_Face = L34_1
L33_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L33_1.m_Pos = "C"
L34_1 = "흥, 나유카 가문의 존속이여."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "ふん、奈由香家の子息よ。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "You, the remnant of the Nayuka family."
L33_1.m_Talk_ENG = L34_1
L34_1 = "哼，南裕夏家族的後裔，"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เจ้า เจ้าซากเหลือของตระกูลนายูกะ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Ngươi, tàn dư của gia tộc Nayuka."
L33_1.m_Talk_VTN = L34_1
L34_1 = "哼，峰奈家族的后代。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Du, der Überrest der Familie Nayuka."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Encore toi, le rejeton Nayuka ?"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "NANAHARA_ACT4_STAGE3_END@234#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 234
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 3600406
L34_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L34_1.m_Pos = "C"
L35_1 = "너는 크나큰 착각을 하고 있구나."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "貴様は大きな勘違いをしているぞ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "You’re making a grave mistake."
L34_1.m_Talk_ENG = L35_1
L35_1 = "你好像有很大的誤解。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "แกทำผิดมหันต์แล้ว"
L34_1.m_Talk_THA = L35_1
L35_1 = "Ngươi đang mắc một sai lầm nghiêm trọng."
L34_1.m_Talk_VTN = L35_1
L35_1 = "你可能产生了很大错觉。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Du machst einen großen Fehler."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Désolée de briser ton illusion, mais tu fais erreur."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "NANAHARA_ACT4_STAGE3_END@235#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 235
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 3600406
L35_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L35_1.m_Pos = "C"
L36_1 = "그래, 네가 정말 네 선조처럼 별을 떨어트릴 수 있다면 날 쓰러트릴 수도 있겠지."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "貴様が本当に先祖のように星を落とすことができるのなら、\n我を倒すこともできよう。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Yes, you might slay me if you could shoot down a star like your ancestor did."
L35_1.m_Talk_ENG = L36_1
L36_1 = "沒錯，若你能像你的祖先一樣射下星星，那你或許能打倒我。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "จริงอยู่ว่าเจ้าคงฆ่าข้าได้ ถ้าเจ้ายิงดวงดาวให้ร่วงหล่นลงมาได้เหมือนบรรพบุรุษ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Đúng, ngươi có thể giết ta nếu ngươi có thể bắn hạ một ngôi sao như tổ tiên của ngươi đã làm."
L35_1.m_Talk_VTN = L36_1
L36_1 = "如果你真的能像自己的先祖那样射落星辰，确实可以打败我。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Ganz recht, du könntest mich töten, wenn du einen Stern abschießen könntest, wie es dein Vorfahr einst getan hat."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Si tu pouvais abattre les étoiles comme ton ancêtre, je ne dis pas..."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "NANAHARA_ACT4_STAGE3_END@236#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 236
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 3600406
L36_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_Face = "UNIT_PRIDE"
L36_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L36_1.m_Pos = "C"
L37_1 = "하지만 그땐 하야미 가문의 무사가 내 발을 묶어 두고 함께 희생했기에 가능한 일이었다."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "だが、あの時は速水家の武士が我を足止めし、\n諸共犠牲になったからこそ可能なことだった。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "But back then, they succeeded only because a Hayami warrior hindered me by sacrificing herself."
L36_1.m_Talk_ENG = L37_1
L37_1 = "但當時是速水家族的武士拖著我一起犧牲，才會發生那種事。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "แต่ตอนนั้น พวกมันทำเสร็จได้ก็เพราะนักรบฮายามิขัดขวางข้าด้วยการสละตัวเอง"
L36_1.m_Talk_THA = L37_1
L37_1 = "Nhưng hồi đó, họ thành công chỉ vì một chiến binh Hayami đã cản trở ta bằng cách tự hy sinh."
L36_1.m_Talk_VTN = L37_1
L37_1 = "但那是因为，当时有速水家族的武士为了困住我，选择牺牲了自己。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Aber damals gelang es nur, weil eine Hayami-Kriegerin mich aufhielt, indem sie sich selbst opferte."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Mais s'il a accompli cet exploit à l'époque, c'est seulement parce qu'une guerrière des Hayami m'avait neutralisé en y perdant la vie."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "NANAHARA_ACT4_STAGE3_END@237#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 237
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 3600406
L37_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L37_1.m_Pos = "C"
L38_1 = "그것은 수많은 인간 놈들의 희생이 아귀가 맞물려 벌어질 수 있었던 우연의 산물이었지."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "それは多くの人間どもの犠牲が重なり合って起きた、偶然の産物だった。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "It was just a coincidence that resulted from countless sacrifices."
L37_1.m_Talk_ENG = L38_1
L38_1 = "那是許多人類一起通力合作，甚至是犧牲才產生的巧合。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "มันเป็นแค่เรื่องบังเอยจากการสละชีวิตนับไม่ถ้วน"
L37_1.m_Talk_THA = L38_1
L38_1 = "Đó chỉ là một sự trùng hợp ngẫu nhiên từ vô số sự hi sinh."
L37_1.m_Talk_VTN = L38_1
L38_1 = "是由无数人类的牺牲产生的叠加效果，是偶然的产物。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Es war nur ein Zufall, der aus unzähligen Opfern resultierte."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Autrement dit, ce n'était rien de plus qu'un miracle né d'innombrables sacrifices."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "NANAHARA_ACT4_STAGE3_END@238#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 238
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 3600406
L38_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L38_1.m_Pos = "C"
L39_1 = "그런데 연합이 서로를 배반하기 바쁜 지금에 와서……"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "なのに、連合が忙しなく互いを裏切る今……"
L38_1.m_Talk_JPN = L39_1
L39_1 = "But now the Alliance has turned against each other..."
L38_1.m_Talk_ENG = L39_1
L39_1 = "但是聯盟現在忙著搞內鬨……"
L38_1.m_Talk_TWN = L39_1
L39_1 = "แต่ตอนนี้สมาพันธ์ก็ขัดแย้งกันเองหมดแล้ว..."
L38_1.m_Talk_THA = L39_1
L39_1 = "Nhưng bây giờ Liên Minh đã trở mặt với nhau..."
L38_1.m_Talk_VTN = L39_1
L39_1 = "但现在整个联盟都分崩离析了……"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Aber jetzt hat sich die Allianz gegeneinander gewandt ..."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Mais aujourd'hui, avec les luttes intestines qui gangrènent le Clan..."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "NANAHARA_ACT4_STAGE3_END@239#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 239
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 3600406
L39_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "OROCHI_JAPAN_NULL_NULL"
L39_1.m_Pos = "C"
L40_1 = "예전과 같은 일이 일어날 수 있을 거라 생각하느냐?"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "かつてのようなことが起こり得ると思うか？"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Do you think you’ll have the luxury of such a coincidence again?"
L39_1.m_Talk_ENG = L40_1
L40_1 = "你認爲還會發生像以前那樣的事嗎？"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เจ้ายังคิดว่าเรื่องบังเอิญแบบนั้นยังจะเกิดขึ้นอีกได้หรือ?"
L39_1.m_Talk_THA = L40_1
L40_1 = "Ngươi nghĩ rằng ngươi sẽ may mắn có được sự trùng hợp ngẫu nhiên như vậy một lần nữa sao?"
L39_1.m_Talk_VTN = L40_1
L40_1 = "你以为还会发生与以前相同的奇迹吗？"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Glaubst du, du wirst den Luxus eines solchen Zufalls noch einmal haben?"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Penses-tu vraiment qu'un tel miracle pourrait se produire de nouveau ?"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
