L46_1.m_Pos = "C"
L46_1.m_Crash = 20
L47_1 = "넌 이미 죽었을 텐데? 어떻게 살아있는 거지?!"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "貴様は死んだはずだが？　どうして生きておる！？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "You already died. How are you still alive?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "你應該已經死了？怎麼會還活著？！"
L46_1.m_Talk_TWN = L47_1
L47_1 = "เจ้าตายไปแล้วนี่ ทำไมยังมีชีวิตอยู่อีก?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Ngươi đã chết rồi. Sao ngươi vẫn còn sống?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "你应该死了才对？为什么还活着？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Du bist doch schon gestorben. Wie ... Wie lebst du noch?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Comment est-ce possible ? Tu es morte, ce jour-là..."
L46_1.m_Talk_FRA = L47_1
