L49_1 = "KANADE_JAPAN_NULL_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "저승길을 잠시 거슬러왔을 뿐이란다."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "少しの間、三途の川を遡ってきただけだ。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "I came back from the dead only for a short while."
L48_1.m_Talk_ENG = L49_1
L49_1 = "我只是暫時回到現世而已，"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ฉันแค่กลับจากความตายมาสั้นๆ"
L48_1.m_Talk_THA = L49_1
L49_1 = "Ta đã trở về từ cõi chết chỉ trong một thời gian ngắn."
L48_1.m_Talk_VTN = L49_1
L49_1 = "只是暂时从黄泉路上逆行归来而已。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Ich bin nur für kurze Zeit von den Toten zurückgekehrt,"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Plus précisément, je suis momentanément revenue d'entre les morts."
L48_1.m_Talk_FRA = L49_1
