L50_1 = "为了回来拖住你。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "um dich aufzuhalten."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Pour mettre un terme à tes agissements."
