L3_1 = "NANAHARA_ACT4_STAGE3_END@252#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 252
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 3600406
L2_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L3_1 = "생명을 비롯한 모든 물건에는 작게나마 혼이 깃든 채로 태어납니다."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "生命をはじめ、あらゆるモノはわずかでも必ず魂を宿して生まれます。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Everything in the world has a soul, however small it may be."
L2_1.m_Talk_ENG = L3_1
L3_1 = "包括生命在內的一切，都是有靈魂的。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ทุกอย่างในโลกนี้มีวิญญาณอยู่ จะเล็กจะน้อยแค่ไหนก็มี"
L2_1.m_Talk_THA = L3_1
L3_1 = "Mọi thứ trên đời đều có linh hồn, dù nhỏ bé đến đâu."
L2_1.m_Talk_VTN = L3_1
L3_1 = "包括生命在内的所有物品，都蕴含着魂。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Alles auf der Welt hat eine Seele, so klein die Sache auch sein mag."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Toutes les choses de ce monde ont une âme, aussi petite soit-elle."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "NANAHARA_ACT4_STAGE3_END@253#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 253
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 3600406
L3_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_IDLE"
L3_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L3_1.m_Pos = "C"
L4_1 = "활과 같은 도구 또한 마찬가지."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "弓のような道具も同じです。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "So do tools, like this bow."
L3_1.m_Talk_ENG = L4_1
L4_1 = "像是弓箭這類的工具也是一樣。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เครื่องมือต่างๆ อย่างคันศรนี่ก็เช่นกัน"
L3_1.m_Talk_THA = L4_1
L4_1 = "Các công cụ cũng vậy, như cây cung này."
L3_1.m_Talk_VTN = L4_1
L4_1 = "弓和其他工具也是一样。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Also Werkzeuge wie dieser Bogen."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Il en va de même pour les objets physiques, comme cet arc."
L3_1.m_Talk_FRA = L4_1
