L5_1 = "NANAHARA_ACT4_STAGE3_END@254#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 254
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 3600406
L4_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L4_1.m_Pos = "C"
L5_1 = "오래된 물건일수록 그것의 혼은 사용자의 사념을 품은 형태로 성장하게 되죠."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "古いモノほど、その魂は持ち主の思念を抱き、成長するのです。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "When an item grows old, its soul begins to bear the will of its owner."
L4_1.m_Talk_ENG = L5_1
L5_1 = "越是古老的東西，裡面的靈魂就會照著使用者的思念成長。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "พอข้าวของอายุมากขึ้น วิญญาณของมันก็แบกเอาเจตจำนงของผู้เป็นเจ้าของไว้"
L4_1.m_Talk_THA = L5_1
L5_1 = "Khi một món đồ già đi, linh hồn của nó bắt đầu mang ý muốn của Chủ Nhân."
L4_1.m_Talk_VTN = L5_1
L5_1 = "古老的物品，它的魂也会以念灵的形式成长。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Wenn ein Gegenstand alt wird, beginnt seine Seele den Willen seines Besitzers zu tragen."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Lorsqu'un objet vieillit, il hérite de l'âme de son propriétaire."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "NANAHARA_ACT4_STAGE3_END@255#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 255
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 3600406
L5_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "UNIT_LAUGH"
L5_1.m_Face = L6_1
L5_1.m_CharStrID = "CHINATSU_NANA_NULL_NULL"
L5_1.m_Pos = "C"
L6_1 = "저는 그 사념의 귀를 열어 부탁할 뿐이랍니다."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "私はその思念に耳を傾けて、願っただけですよ。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "All I do is ask for the will to help."
L5_1.m_Talk_ENG = L6_1
L6_1 = "我只是打開思念的耳朵拜託它而已。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ที่ฉันทำก็แค่ขอความช่วยเหลือจากเจตจำนงนั่นค่ะ"
L5_1.m_Talk_THA = L6_1
L6_1 = "Tất cả những gì tôi làm là nhờ ý chí giúp đỡ."
L5_1.m_Talk_VTN = L6_1
L6_1 = "我只是让念灵帮忙而已。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Ich bitte nur um den Willen zu helfen."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Tout ce que je fais, c'est chuchoter à l'oreille de cette âme. Pour lui demander de m'aider."
L5_1.m_Talk_FRA = L6_1
