L8_1.m_Pos = "C"
L9_1 = "가면에 깃든 사념을…… 신력으로 실체를 만들었다고?!"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "面に宿った思念を……神力で実体を作ったのか！？"
L8_1.m_Talk_JPN = L9_1
L9_1 = "The will within the mask was materialized by divine power?"
L8_1.m_Talk_ENG = L9_1
L9_1 = "神力讓面具上的思念……化作實體？！"
L8_1.m_Talk_TWN = L9_1
L9_1 = "เจตจำนงในหน้ากากเป็นรูปเป็นร่างขึ้นมาด้วยพลังเทวะงั้นเหรอ?"
L8_1.m_Talk_THA = L9_1
L9_1 = "Ý chí bên trong chiếc mặt nạ đã được hiện thực hóa bằng sức mạnh thần thánh?"
L8_1.m_Talk_VTN = L9_1
L9_1 = "藉由假面中的念灵……用神力创造了实体？"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Der Wille in der Maske wurde tatsächlich durch göttliche Kraft materialisiert?"
L8_1.m_Talk_DEU = L9_1
L9_1 = "L'âme du masque à été matérialisée par les pouvoirs divins ?"
L8_1.m_Talk_FRA = L9_1
