L10_1 = "그건 불가능해! 본래의 육신을 이곳에 묻어둔 게 아닌 이상에야……!"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "それは不可能だ！\n本来の肉体をここに埋めておいたのでもない以上……！"
L9_1.m_Talk_JPN = L10_1
L10_1 = "That’s impossible, unless your body is buried here..."
