L10_1 = "那是不可能的！除非把原本的軀體埋在這裡…！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "เป็นไปไม่ได้ เว้นแต่ร่างเจ้าจะถูกฝังไว้ที่นี่..."
L9_1.m_Talk_THA = L10_1
L10_1 = "Điều đó là không thể, trừ khi cơ thể của ngươi được chôn cất ở đây..."
L9_1.m_Talk_VTN = L10_1
L10_1 = "这不可能！如果没有原本的躯体的话……！"
