L18_1 = "KANADE_JAPAN_NULL_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "C"
L18_1 = "이걸로 너와 내가 빠져나갈 구멍은 없다."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "これで貴様と私の逃げ道はない。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Now, there is no escape for us."
L17_1.m_Talk_ENG = L18_1
L18_1 = "這樣你和我都沒得逃。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ทีนี้ก็ไม่มีทางหนีจากพวกเราไปได้แล้ว"
L17_1.m_Talk_THA = L18_1
L18_1 = "Bây giờ, không có lối thoát cho chúng ta."
L17_1.m_Talk_VTN = L18_1
L18_1 = "这样你和我都没办法逃了。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Jetzt gibt es für uns kein Entrinnen mehr."
L17_1.m_Talk_DEU = L18_1
L18_1 = "C'est fini, tu ne peux plus t'échapper."
L17_1.m_Talk_FRA = L18_1
