L25_1 = "MINATO_NANA_NULL_NULL"
L24_1.m_CharStrID = L25_1
L25_1 = "사람이 더럽혀지기 전에 삶을 거두어 간다고 했지?"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "人が穢れる前に命を奪ってやると言ったよな？"
L24_1.m_Talk_JPN = L25_1
L25_1 = "You said you were going to take our lives before we became corrupted."
L24_1.m_Talk_ENG = L25_1
L25_1 = "你不是說過，要到受到污染前結束人生嗎？"
L24_1.m_Talk_TWN = L25_1
L25_1 = "เธอบอกว่าจะเอาชีวิตเราไปก่อนที่มันจะแปดเปื้อนใช่มั้ยล่ะ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Bà đã nói rằng bà sẽ lấy đi mạng sống của chúng tôi trước khi chúng tôi bị tha hóa."
L24_1.m_Talk_VTN = L25_1
L25_1 = "你说你想要在人类被玷污前收割他们灵魂是吗？"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Du sagtest, Du würdest uns das Leben nehmen, bevor wir verderben."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Tu disais que tu allais nous ôter la vie avant que les ténèbres nous gagnent, n'est-ce pas ?"
L24_1.m_Talk_FRA = L25_1
