L31_1 = "NANAHARA_ACT4_STAGE3_END@280#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 280
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 3600406
L30_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "MINATO_NANA_NULL_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "하지만 모든 인간이 깨끗하지 못하다고 해서, 인간의 남은 희망마저 부정할 순 없어."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "だけど、すべての人間が綺麗じゃないからといって、\n人間が残した希望まで否定することはできない。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Some people are corrupted; that’s true. But you can’t deny hope from everyone just because of them."
L30_1.m_Talk_ENG = L31_1
L31_1 = "但是不能因爲所有的人都不潔淨，就否定人類留下的希望。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ก็จริงอยู่ว่ามนุษย์บางคนอาจแปดเปื้อน แต่จะเอาเรื่องนั้นมาปฏิเสธความหวังของทุกคนไม่ได้หรอกนะ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Một số người bị tha hóa, đó là sự thật. Nhưng bà không thể phủ nhận hy vọng từ tất cả mọi người chỉ vì họ."
L30_1.m_Talk_VTN = L31_1
L31_1 = "但就算人类不再纯洁，也不能否定他们留下的希望。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Manche Menschen sind verderbt, das ist richtig. Aber man kann nicht jedem einzelnen die Hoffnung nehmen, nur weil einige von ihnen so sind."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Tu as raison, l'humanité compte effectivement des mauvaises graines dans ses rangs. Mais ce n'est pas une raison pour priver d'espoir le monde entier."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "NANAHARA_ACT4_STAGE3_END@281#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 281
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 3600406
L31_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "MINATO_NANA_NULL_NULL"
L31_1.m_CharStrID = L32_1
L32_1 = "당신은 인간들과 다르고, 강하며, 인간의 모든 내면을 꿰뚫고 있다고 생각했겠지만……"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "お前は人間と違い、強く、人間のあらゆる内心を見抜いていると思っていたんだろうけど……"
L31_1.m_Talk_JPN = L32_1
L32_1 = "You might have thought that you were different from us, stronger than us, and know everything about us..."
L31_1.m_Talk_ENG = L32_1
L32_1 = "你可能以爲你和人類不同，你很強，又能看透人心……"
L31_1.m_Talk_TWN = L32_1
L32_1 = "เธออาจคิดว่าตัวเองไม่เหมือนเรา แข็งแกร่งกว่าเรา และก็รู้ทุกอย่างเกี่ยวกับเรา..."
L31_1.m_Talk_THA = L32_1
L32_1 = "bà có thể nghĩ rằng bà khác với chúng tôi, mạnh mẽ hơn và biết mọi thứ về chúng tôi..."
L31_1.m_Talk_VTN = L32_1
L32_1 = "你认为自己与人类不同，比人类强大，认为自己洞察了人类的内心……"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Vielleicht dachtest du, du wärst anders als wir, stärker als wir und wüsstest alles über uns ..."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Tu croyais que tu étais différent, n'est-ce pas ? Que tu étais plus fort, que tu savais tout de nous..."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "NANAHARA_ACT4_STAGE3_END@282#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 282
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 3600406
L32_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "MINATO_NANA_NULL_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "당신이야말로 상처입고 병들었을 뿐인, 여느 인간과 다름없는 연약한 존재야."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "お前こそ傷つき病にかかっただけの、普通の人間と変わらない弱い存在だ。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "But you are actually as fragile as us, wounded and sick."
L32_1.m_Talk_ENG = L33_1
L33_1 = "但其實你和人類一樣脆弱，一樣會受傷，一樣會生病。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "แต่จริงๆ แล้วเธอก็เปราะบางเหมือนเรานั่นแหละ บาดเจ็บและเจ็บป่วยได้"
L32_1.m_Talk_THA = L33_1
L33_1 = "Nhưng bà thực sự cũng mong manh như chúng tôi, cũng bị thương và mắc bệnh."
L32_1.m_Talk_VTN = L33_1
L33_1 = "但其实你才是受到伤害最深的那个，你与软弱的人类没任何不同。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Aber du bist eigentlich genauso zerbrechlich wie wir. Verwundet und krank."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Mais en réalité tu n'es qu'un être malade et fragile, blessé dans ton orgueil."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "NANAHARA_ACT4_STAGE3_END@283#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 283
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 3600406
L33_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "MINATO_NANA_NULL_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "자신의 복수를 행하고, 그 뒤에 그럴싸한 이유를 붙일 뿐인, 그런 평범한 악인이었을 뿐이지."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "自分の復讐を行い、その後にもっともらしい理由をつけただけの、\nそんな平凡な悪人にすぎない。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "You’re a plain villain who is only trying to justify your revenge."
L33_1.m_Talk_ENG = L34_1
L34_1 = "你只是替自己的行為找到一個看似合理藉口的壞人。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เธอเป็นแค่วายร้ายที่หาความชอบธรรมให้การล้างแค้นของตัวเองเท่านั้น"
L33_1.m_Talk_THA = L34_1
L34_1 = "bà là một nhân vật phản diện đơn thuần chỉ đang cố gắng biện minh cho sự trả thù của mình."
L33_1.m_Talk_VTN = L34_1
L34_1 = "为了自己的复仇，捏造了看似合理的理由。你只是个普通的恶人而已。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Du bist eine einfache Schurkin, die nur versucht, ihre Rache zu rechtfertigen."
L33_1.m_Talk_DEU = L34_1
L34_1 = "En somme, un super-vilain qui s'invente des prétextes pour légitimer sa vengeance."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
