L36_1.m_fBGCrashTime = 0.5
L37_1 = "MINATO_NANA_NULL_NULL"
L36_1.m_CharStrID = L37_1
L37_1 = "이제 빼앗긴 일상을 돌려받겠어!"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "奪われた僕の日常を返してもらう！"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Give us back our everyday lives!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "我要找回被奪走的平凡生活！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "เอาชีวิตธรรมดาของเราคืนมาซะ!"
L36_1.m_Talk_THA = L37_1
L37_1 = "Hãy trả lại cho chúng tôi cuộc sống bình thường!"
L36_1.m_Talk_VTN = L37_1
L37_1 = "也只是个想要取回被夺走日常生活的普通人罢了！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Gib uns unseren Alltag zurück!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Rends-moi la vie tranquille que tu m'as volé !"
L36_1.m_Talk_FRA = L37_1
