L48_1 = "NANAHARA_ACT4_STAGE3_END@297#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 297
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 3600406
L47_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "FX_CUTSCEN_HEARTBEAT"
L47_1.m_StartFXSoundName = L48_1
L48_1 = "사람은…… 우리처럼 천수를 누리지 못해."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "人は……私たちのように永遠を生きることはできない。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Humans don’t live forever, like us."
L47_1.m_Talk_ENG = L48_1
L48_1 = "人…… 無法像我們一樣享有天壽。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "มนุษย์ไม่ได้มีชีวิตอยู่ไปตลอดกาลแบบเราหรอกนะ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Con người không sống mãi mãi, giống như chúng ta."
L47_1.m_Talk_VTN = L48_1
L48_1 = "人类……无法像我们一样永生。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Menschen leben nicht ewig wie wir."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Les humains ne sont pas comme nous, ils ne vivent pas éternellement."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "NANAHARA_ACT4_STAGE3_END@298#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 298
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 3600406
L48_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "FX_CUTSCEN_HEARTBEAT"
L48_1.m_StartFXSoundName = L49_1
L49_1 = "짧은 삶을 살기 때문에, 처음부터 실수와 후회를 반복하며 성장한단다."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "短い人生を送るため、生まれてからずっと\n過ちと後悔を繰り返しながら成長するもの。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "They have short lives. They grow up by repeating mistakes and regrets."
L48_1.m_Talk_ENG = L49_1
L49_1 = "因爲生命很短暫，所以一出生就在不斷的犯錯和後悔中成長。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ชีวิตพวกเขาแสนสั้น พวกเขาเติบโตขึ้นด้วยการทำผิดและเสียใจซ้ำๆ"
L48_1.m_Talk_THA = L49_1
L49_1 = "Họ có cuộc sống ngắn ngủi. Họ lớn lên bằng cách lặp lại những sai lầm và hối tiếc."
L48_1.m_Talk_VTN = L49_1
L49_1 = "因为他们生命短暂，所以会不断重复着犯错与后悔，只有这样他们才能成长。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Sie haben ein kurzes Leben. Sie wachsen auf, indem sie Fehler und Reue dauernd wiederholen."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Leur vie est courte. Une succession d'erreurs, et de regrets."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "NANAHARA_ACT4_STAGE3_END@299#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 299
