L49_1.m_CutScenID = 3600406
L49_1.m_CutScenStrID = "NANAHARA_ACT4_STAGE3_END"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "FX_CUTSCEN_HEARTBEAT"
L49_1.m_StartFXSoundName = L50_1
L50_1 = "그러니…… 부디."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
