L51_1 = "Đừng ghét họ vì cái chết của tôi, Orochi."
L50_1.m_Talk_VTN = L51_1
L51_1 = "不要因为我的死，就憎恨人类。大蛇。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "hasse sie nicht für meinen Tod, Orochi."
L50_1.m_Talk_DEU = L51_1
